<template><aside v-if="unavailable.length" class="dp-network-status" aria-live="polite"><details><summary>{{ $t('Other network status') }} ({{ unavailable.length }})</summary><p v-for="n in unavailable" :key="n.id"><network-icon :network-id="n.id" :name="n.name"/><strong>{{n.name}}</strong> — {{n.message}}</p><Link :href="route('support')">{{ $t('Contact support') }}</Link></details></aside></template>
<script>export default{props:{networks:{type:Array,default:()=>[]}},computed:{unavailable(){return this.networks.filter(n=>!n.available)}}};</script>
<style scoped>.dp-network-status{margin:10px 0;padding:12px;border:1px solid #ac934755;border-radius:8px;font-size:13px}.dp-network-status summary{cursor:pointer}.dp-network-status p{margin-top:8px;overflow-wrap:anywhere}.dp-network-status a{text-decoration:underline}</style>
